-- ============================================================================
-- Map 100 REAL authored Scrum questions → live v2 flagship (0-BASED order_index).
-- CORRECTED reissue of 20260619020000: the live v2 course stores chapters with
-- 0-based order_index (0..17), but 020000 looked them up 1-based (1..18), so the
-- module-18 lookup (order_index=18) returned no row -> NULL quiz_id -> the whole
-- block aborted (no partial data). This version shifts every quiz lookup by -1
-- (1->0, 2->1, 4->3, 10->9, 12->11, 13->12, 18->17) and adds hard guards.
-- Maps ONLY quiz_questions onto EXISTING quizzes — inserts 0 lessons, 0 quizzes.
-- Apply by hand in Supabase (Claude does not auto-apply). Partial coverage:
-- 100 questions across 7 of 18 modules — NOT the 1,080-question bank.
-- ============================================================================
ALTER TABLE public.quiz_questions ADD COLUMN IF NOT EXISTS translations JSONB DEFAULT '{}'::jsonb;
DO $$
DECLARE cid uuid; qz uuid; n int;
BEGIN
  SELECT id INTO cid FROM public.courses WHERE is_flagship ORDER BY created_at LIMIT 1;
  IF cid IS NULL THEN RAISE EXCEPTION 'Flagship course not found'; END IF;
  -- ---- v2-safe hard guards (0-based order_index; populated v2 course) ----
  IF cid <> 'f46d8fc2-50e4-4bd8-91da-f8bac4f7ba14' THEN
    RAISE EXCEPTION 'Flagship id % is not the expected v2 course — aborting', cid; END IF;
  SELECT count(*) INTO n FROM public.chapters WHERE course_id=cid;
  IF n <> 18 THEN RAISE EXCEPTION 'Expected 18 modules, found % — aborting', n; END IF;
  SELECT count(*) INTO n FROM public.videos v JOIN public.chapters c ON c.id=v.chapter_id WHERE c.course_id=cid;
  IF n <> 162 THEN RAISE EXCEPTION 'Expected 162 lessons, found % — aborting', n; END IF;
  SELECT count(*) INTO n FROM public.quizzes q JOIN public.chapters c ON c.id=q.chapter_id WHERE c.course_id=cid AND q.quiz_type='chapter_end';
  IF n <> 18 THEN RAISE EXCEPTION 'Expected 18 chapter_end quizzes, found % — aborting', n; END IF;
  SELECT count(*) INTO n FROM public.quiz_questions qq JOIN public.quizzes q ON q.id=qq.quiz_id JOIN public.chapters c ON c.id=q.chapter_id WHERE c.course_id=cid;
  IF n > 0 THEN RAISE EXCEPTION 'Flagship already has % mapped question(s) — aborting to avoid duplicates', n; END IF;
  -- the 7 target chapters (0-based) must each have a chapter_end quiz
  SELECT count(*) INTO n FROM public.chapters c JOIN public.quizzes q ON q.chapter_id=c.id AND q.quiz_type='chapter_end'
    WHERE c.course_id=cid AND c.order_index IN (0,1,3,9,11,12,17);
  IF n <> 7 THEN RAISE EXCEPTION 'Expected 7 target chapter_end quizzes (order_index 0,1,3,9,11,12,17), found % — aborting', n; END IF;
  RAISE NOTICE 'Guards passed: v2 flagship, 18 modules / 162 lessons / 18 quizzes / 0 questions; mapping 100 questions (0-based).';

  -- Module 1: 1 questions
  SELECT q.id INTO qz FROM public.quizzes q JOIN public.chapters c ON c.id=q.chapter_id
    WHERE c.course_id=cid AND c.order_index=0 AND q.quiz_type='chapter_end' LIMIT 1;

  -- Module 2: 5 questions
  SELECT q.id INTO qz FROM public.quizzes q JOIN public.chapters c ON c.id=q.chapter_id
    WHERE c.course_id=cid AND c.order_index=1 AND q.quiz_type='chapter_end' LIMIT 1;

  -- Module 4: 3 questions
  SELECT q.id INTO qz FROM public.quizzes q JOIN public.chapters c ON c.id=q.chapter_id
    WHERE c.course_id=cid AND c.order_index=3 AND q.quiz_type='chapter_end' LIMIT 1;

  -- Module 10: 4 questions
  SELECT q.id INTO qz FROM public.quizzes q JOIN public.chapters c ON c.id=q.chapter_id
    WHERE c.course_id=cid AND c.order_index=9 AND q.quiz_type='chapter_end' LIMIT 1;

  -- Module 12: 10 questions
  SELECT q.id INTO qz FROM public.quizzes q JOIN public.chapters c ON c.id=q.chapter_id
    WHERE c.course_id=cid AND c.order_index=11 AND q.quiz_type='chapter_end' LIMIT 1;

  -- Module 13: 37 questions
  SELECT q.id INTO qz FROM public.quizzes q JOIN public.chapters c ON c.id=q.chapter_id
    WHERE c.course_id=cid AND c.order_index=12 AND q.quiz_type='chapter_end' LIMIT 1;

  -- Module 18: 40 questions
  SELECT q.id INTO qz FROM public.quizzes q JOIN public.chapters c ON c.id=q.chapter_id
    WHERE c.course_id=cid AND c.order_index=17 AND q.quiz_type='chapter_end' LIMIT 1;
END $$;

